var gnMaxNumDhcpStaticIP=ARC_DEF_LAN_DHCP4S_STATIC_IP_MAXNUM;
function init_form_data()
{
var aTmp,szTmp,ki,szIndex,oField;
szTmp=getCfg("lan_ip");
if(isValidIP(szTmp,0)){
aTmp=szTmp.split(".");
$I("id_ip_addr_0").value=aTmp[0];
$I("id_ip_addr_1").value=aTmp[1];
$I("id_ip_addr_2").value=aTmp[2];}
if(gnIsAdd!=0){
if(gnEntryIndex<0){
for(ki=0;ki<gnMaxNumDhcpStaticIP;ki++){
szTmp=getCfg("static_mac_0_"+ki.toString());
if(szTmp.replace(gexpTrim,"")==""){
gnEntryIndex=ki;
break;}}}
if(gnEntryIndex<0||gnEntryIndex>=gnMaxNumDhcpStaticIP){
JumpURL("lan_dhcp_static.htm");}
return false;}
if(gnEntryIndex>=gnMaxNumDhcpStaticIP){
JumpURL("lan_dhcp_static.htm");
return false;}
szIndex=gnEntryIndex.toString();
szTmp=getCfg("static_active_0_"+szIndex);
if(szTmp!="1"){$I("id_dhcp_static_active").checked=false;}
szTmp=getCfg("static_mac_0_"+szIndex);
if(!gexpMAC.test(szTmp)){
return false;}
aTmp=szTmp.split(":");
for(ki=0;ki<aTmp.length;ki++){
oField=$I("id_mac_addr_"+ki.toString());
oField.value=aTmp[ki];
DisableObject(oField);}
szTmp=getCfg("static_ip_0_"+szIndex);
if(isValidIP(szTmp,0)){
aTmp=szTmp.split(".");
$I("id_ip_addr_3").value=aTmp[3];}
aTmp=null;
szTmp=getCfg("static_name_0_"+szIndex);
$I("id_hostname").value=szTmp;
return true;}
function dhcp_clients_request()
{
do_jload([["cgi/cgi_clients.js"]],function(errCode){
if(errCode==0){
init_table_dhcp_clients();}});
return false;}
function init_table_dhcp_clients()
{
var nRowCount=0,oRowCell,c1,c2,c3,c4;
var ki,szIndex,szAddrIP,szAddrMAC,szHostName,szRadio,szEditMAC;
var fmt_radio='<input type="radio" name="id_radio_client" value="{id1}" onClick="event_radio_client(this.value);">';
szEditMAC="";
if(typeof(gnIsAdd)=="number"){
if(gnIsAdd==0){
szEditMAC=getCfg("static_mac_0_"+gnEntryIndex.toString());
if(!gexpMAC.test(szEditMAC)){
szEditMAC="";}}}
if(dhcp_client instanceof Array){
for(ki=0;ki<dhcp_client.length;ki+=5){
szIndex=nRowCount.toString();
szRadio=fmt_str(fmt_radio,szIndex);
szHostName=dhcp_client[ki];
szAddrIP=dhcp_client[ki+1];
szAddrMAC=dhcp_client[ki+2].toUpperCase();
if(szEditMAC.length==17){
if(szEditMAC==szAddrMAC){
szEditMAC=szIndex;}}
var cell_html='<div class="radio"><label>'+szRadio+'<span style="padding-left:25px;">'+'<span style="display:table-cell;width:155px;">'+szAddrMAC+'</span>'+'<span style="display:table-cell;width:145px;">'+szAddrIP+'</span>'+'<span style="display:table-cell;">'+szHostName+'</span></span></label></div>';
c1=[1,cell_html,null];
oRowCell=[c1,[null,null]];
nRowCount+=Table_add_row("id_table_dhcp_clients",[[1,nRowCount,0],oRowCell],1);
oRowCell=null;}}
if(szEditMAC.length>0){
if(/[0-9]+/.test(szEditMAC)){
setIdVal(0,szEditMAC,document.formMain.id_radio_client);}}
oRowCell=nRowCount=null;}
function init_event_onKeyPress()
{
$I("id_mac_addr_0").onkeypress=event_onKeyPress_isHex;
$I("id_mac_addr_1").onkeypress=event_onKeyPress_isHex;
$I("id_mac_addr_2").onkeypress=event_onKeyPress_isHex;
$I("id_mac_addr_3").onkeypress=event_onKeyPress_isHex;
$I("id_mac_addr_4").onkeypress=event_onKeyPress_isHex;
$I("id_mac_addr_5").onkeypress=event_onKeyPress_isHex;
$I("id_ip_addr_0").onkeypress=event_onKeyPress_isNumber;
$I("id_ip_addr_1").onkeypress=event_onKeyPress_isNumber;
$I("id_ip_addr_2").onkeypress=event_onKeyPress_isNumber;
$I("id_ip_addr_3").onkeypress=event_onKeyPress_isNumber;}
function event_onKeyPress_isHex(event)
{
event=(event)?event:window.event
var charCode=(event.which)?event.which:event.keyCode
switch(charCode){
case 8:
case 9:
case 35:
case 36:
case 37:
case 39:
case 46:
return true;
default:
if(charCode>=48&&charCode<=57){
return true;}
if(charCode>=65&&charCode<=70){
return true;}
if(charCode>=97&&charCode<=102){
return true;}}
AlertM("970032");
return false;}
function event_onKeyPress_isNumber(event)
{
event=(event)?event:window.event
var charCode=(event.which)?event.which:event.keyCode
switch(charCode){
case 8:
case 9:
case 35:
case 36:
case 37:
case 39:
case 46:
return true;
default:
if(charCode>=48&&charCode<=57){
return true;}}
AlertM("970031");
return false;}
function event_edit_field_disable(_bDisable)
{
if(_bDisable==true){
for(var ki=0;ki<6;ki++){
DisableObject("id_mac_addr_"+ki.toString());}}
else{
for(var ki=0;ki<6;ki++){
EnableObject("id_mac_addr_"+ki.toString());}}}
function event_radio_client(_client_index)
{
if(_client_index=="manually"){
for(var ki=0;ki<6;ki++){
$I("id_mac_addr_"+ki.toString()).value="";}
$I("id_ip_addr_3").value="";
$I("id_hostname").value="";
event_edit_field_disable(false);
return true;}
var expClientIndex=/^[0-9]{1,4}$/;
if(expClientIndex.test(_client_index)==false){
return false;}
var nClientIndex=parseInt(_client_index);
var oTableClient=$I("id_table_dhcp_clients");
if((nClientIndex+1)>oTableClient.rows.length){
return false;}
var oRow=oTableClient.rows[nClientIndex];
var aCell=oRow.cells;
var $td=$("#id_table_dhcp_clients td").eq(nClientIndex);
var szMAC=$td.find("label>span:eq(1) span:eq(0)").html();
var szIP=$td.find("label>span:eq(1) span:eq(1)").html();
var szHost=$td.find("label>span:eq(1) span:eq(2)").html();
var aMAC=szMAC.split(":");
var aIP=szIP.split(".");
if(aMAC instanceof Array){
for(var ki=0;ki<aMAC.length;ki++){
$I("id_mac_addr_"+ki.toString()).value=aMAC[ki];}}
if(aIP instanceof Array){
if(aIP.length==4){
$I("id_ip_addr_3").value=aIP[3];}}
$I("id_hostname").value=szHost;
event_edit_field_disable(true);
oRow=aCell=szMAC=szHost=aMAC=null;}
function examine_UI_data()
{
var szAddrMAC=IP_MAC_address_join("id_mac_addr_",0,6,":");
if(isValidMac(szAddrMAC)==false){
return false;}
var oIPAddr3=$I("id_ip_addr_3");
var szAddrIP=IP_MAC_address_join("id_ip_addr_",0,4,".");
if(!isValidIP(szAddrIP,0))
{
AlertM("361207");
oIPAddr3.focus();
oIPAddr3.select();
return false;}
if(szAddrIP==getCfg("lan_ip"))
{
szAddrIP=getLangM("361208").replace("{id1}",szAddrIP);
alert(szAddrIP);
oIPAddr3.focus();
oIPAddr3.select();
return false;}
var ki,szCfgFixedIP;
for(ki=0;ki<gnMaxNumDhcpStaticIP;ki++){
if(ki==gnEntryIndex){
continue;}
szCfgFixedIP=getCfg("static_ip_0_"+ki.toString());
if(szCfgFixedIP==szAddrIP)
{
AlertM("361209");
oIPAddr3.focus();
oIPAddr3.select();
return false;}}
var szIndex=gnEntryIndex.toString();
var szActive=$I("id_dhcp_static_active").checked?"1":"0";
var szHostname=$I("id_hostname").value;
setCfg("static_active_0_"+szIndex,szActive);
setCfg("static_mac_0_"+szIndex,szAddrMAC.toUpperCase());
setCfg("static_ip_0_"+szIndex,szAddrIP);
setCfg("static_name_0_"+szIndex,szHostname);
setCfg("static_enable","1");
return subForm({
frm:document.idFormMain,
cmd:subFormLANDHCPStatic,
next:"lan_dhcp_static.htm",
wait:4});}
function isValidMac(_addr_mac)
{
if(_addr_mac==":::::")
{
AlertM("361204");
return false;}
_addr_mac=_addr_mac.toLowerCase();
if(_addr_mac=="00:00:00:00:00:00"||_addr_mac=="ff:ff:ff:ff:ff:ff")
{
AlertM("361205");
return true;}
var ki,szCfgMAC;
for(ki=0;ki<gnMaxNumDhcpStaticIP;ki++){
if(ki==gnEntryIndex){
continue;}
szCfgMAC=getCfg("static_mac_0_"+ki.toString()).toLowerCase();
if(szCfgMAC==_addr_mac)
{
AlertM("361206");
return false;}}
return true;}